import { researchPage } from "./research-page";

// The research page is a complete HTML document generated by YouOnAI/site/build.py --portfolio
// (into ./research-page.ts and public/research/). It repeats this site's header, footer and styles.
export function GET() {
  return new Response(researchPage.html, {
    headers: {
      "Content-Type": "text/html; charset=utf-8",
      "Cache-Control": "public, max-age=300, stale-while-revalidate=86400",
      ...(researchPage.publish ? {} : { "X-Robots-Tag": "noindex, nofollow" }),
    },
  });
}
